package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaThDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("ที่หลบภัยจากเพื่อนบ้านที่ไม่ดี", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากเพื่อนบ้านที่ไม่ดีในสถานที่พำนักถาวร เพื่อให้เพื่อนบ้านเดินทางต่อไป", "เพื่อป้องกันเพื่อนบ้านที่ไม่ดี", "ศาสดาพยากรณ์ ﷺ ทรงบัญชาให้ขอความคุ้มครองจากสิ่งนี้"),
        "dua_ishfi_abdak" to DuaText("เพื่อการฟื้นตัวของผู้ป่วย", "โอ้อัลลอฮ์ โปรดรักษาผู้รับใช้ของพระองค์เพื่อที่เขาจะได้เผชิญหน้ากับศัตรูเพื่อพระองค์ หรือเดินไปละหมาดเพื่อพระองค์", "สำหรับคนป่วยเมื่อไปเยี่ยมเขา", "ศาสดาพยากรณ์ ﷺ สอนคำพูดนี้แก่คนป่วย"),
        "dua_la_mania" to DuaText("ไม่มีใครสามารถระงับสิ่งที่คุณให้ได้", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจนั้นเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง โอ้อัลลอฮ์ ไม่มีผู้ใดสามารถยับยั้งสิ่งที่พระองค์ประทานให้ และไม่มีผู้ใดสามารถให้สิ่งที่พระองค์ทรงหวงห้ามได้ และความมั่งคั่งของผู้มั่งคั่งก็ไม่มีประโยชน์ใด ๆ แก่พระองค์เลย", "หลังจากสลามของการสวดมนต์บังคับ", "ศาสดา ﷺ กล่าวสิ่งนี้หลังจากสวดมนต์บังคับทุกครั้ง"),
        "dua_slaughtering" to DuaText("เมื่อเชือดสัตว์", "ด้วยพระนามของอัลลอฮฺ และอัลลอฮ์นั้นทรงยิ่งใหญ่", "เมื่อทำการบูชายัญหรือเชือดสัตว์", "พระศาสดา ﷺ กล่าวบิสมิลลาห์และตักบีร์ในเวลาทำการบูชายัญ"),
        "dua_undressing" to DuaText("เมื่อถอดเสื้อผ้า", "ในนามของอัลลอฮ.", "เมื่อถอดเสื้อผ้า (สำหรับฆุสล์หรือเปลี่ยนเสื้อผ้า)", "มันจะกลายเป็นม่านกั้นระหว่างดวงตาของญินและอวัยวะส่วนตัวของบุคคล"),
        "dua_ilbas_jadidan" to DuaText("เห็นใครบางคนในชุดใหม่", "สวมชุดใหม่ ใช้ชีวิตอย่างน่ายกย่อง และตายอย่างพลีชีพ", "เมื่อได้พบพี่น้องมุสลิมในชุดใหม่", "พระศาสดา ﷺ ดุอานี้เมื่อเห็นอุมัร (RA) ในชุดใหม่"),
        "dua_hajj_la_riya" to DuaText("ฮัจญ์ที่ปราศจากการโอ้อวด", "โอ้อัลลอฮฺ โปรดทรงทำฮัจญ์โดยไม่โอ้อวด และไม่แสวงหาชื่อเสียง", "เพื่อความจริงใจในการทำฮัจญ์", "พระศาสดาหมายเลข ﷺ ทรงทำดุอานี้ในเวลาประกอบพิธีฮัจญ์"),
        "dua_q_muslimayni_laka" to DuaText("Dua ของอิบราฮิมและอิสมาอิล (AS) — ทำให้เรายอมแพ้", "ข้าแต่พระเจ้าของเรา โปรดทรงโปรดให้เราทั้งสองยอมจำนนต่อพระองค์ และจากลูกหลานของเราให้เป็นประชาชาติที่ยอมจำนนต่อพระองค์ แสดงพิธีกรรมการนมัสการของเราและยอมรับการกลับใจของเรา แท้จริงพระองค์คือผู้ทรงรับการสำนึกผิด ผู้ทรงเมตตาเสมอ", "ดุอาแห่งการยอมจำนนต่อตนเองและลูกหลาน", "ดุอาที่ทำขึ้นขณะสร้างกะอ์บะฮ์"),
        "dua_q_iftah_baynana" to DuaText("Dua ของ Shu'aib (AS) — ผู้พิพากษาระหว่างเรา", "พระเจ้าของเรา โปรดตัดสินระหว่างเรากับกลุ่มชนของเราด้วยความจริง และพระองค์คือผู้ตัดสินที่ดีที่สุด", "สำหรับการตัดสินระหว่างความจริงและความเท็จ", "ดุอาอฺชุอัยบ์ (AS) เมื่อหมู่ชนของเขาปฏิเสธเขา"),
        "dua_q_la_akuna_zahiran" to DuaText("Dua ของ Musa (AS) — ไม่เคยเป็นผู้ช่วยเหลืออาชญากร", "พระเจ้าของฉัน เพราะความโปรดปรานที่พระองค์ประทานแก่ฉัน ฉันจะไม่เป็นผู้ช่วยเหลืออาชญากรเลย", "ความกตัญญูต่อพระพรของอัลลอฮ์ และคำมั่นสัญญาที่จะไม่ช่วยเหลือผู้กระทำผิด", "คำมั่นสัญญาของมูซา (AS) หลังจากการกลับใจของเขา"),
        "dua_q_nuh_unsurni" to DuaText("Dua ของ Nuh (AS) — ช่วยฉันด้วย พวกเขาปฏิเสธฉัน", "พระเจ้าของฉัน โปรดช่วยฉันด้วยเพราะพวกเขาได้ปฏิเสธฉันแล้ว", "เมื่อผู้คนปฏิเสธคุณและปฏิเสธความจริง", "ดุอาอ์นูห์ (AS) ซึ่งได้รับการตอบรับ"),
        "dua_q_ihkum_bil_haqq" to DuaText("ข้าแต่พระเจ้าของข้าพระองค์ ทรงพิพากษาด้วยความจริง", "ข้าแต่พระเจ้าของข้าพเจ้า ขอทรงตัดสินด้วยความจริง และพระเจ้าของเราคือผู้ทรงเมตตาเสมอ ผู้ทรงช่วยเหลือในสิ่งที่พวกท่านกล่าวถึง", "เมื่อเผชิญกับการโกหกและข้อกล่าวหาที่เป็นเท็จ", "ดุอาที่สอนท่านศาสดา ﷺ"),
        "dua_ghalabatid_dayn" to DuaText("ที่หลบภัยจากการทลายหนี้และศัตรู", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากการถูกครอบงำด้วยหนี้ จากการถูกศัตรูครอบงำ และจากการจ้องมองของศัตรู", "คุ้มครองจากภาระหนี้สินและการครอบงำของศัตรู", "พระศาสดา ﷺ เคยแสวงหาที่หลบภัยจากสิ่งเหล่านี้"),
        "dua_faqr_qillah_dhillah" to DuaText("ที่ลี้ภัยจากความยากจนและความอับอาย", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความยากจน ความขาดแคลน และความอับอาย และจากการอธรรมต่อผู้อื่นหรือการถูกอธรรม", "ให้พ้นจากความยากลำบาก ความขาดแคลน และความอัปยศอดสู", "ที่หลบภัยที่ศาสดาพยากรณ์ ﷺ สอน"),
        "dua_five_things_new_muslim" to DuaText("ให้อภัย มีความเมตตา นำทาง เยียวยา จัดหา", "โอ้อัลลอฮ์ โปรดอภัยโทษให้ฉัน โปรดเมตตาฉัน โปรดชี้ทางให้ฉัน ให้ความอยู่ดีมีสุขแก่ฉัน และโปรดประทานปัจจัยยังชีพแก่ฉันด้วย", "ศาสดา ﷺ สอน dua นี้พร้อมกับคำอธิษฐานแก่ชาวมุสลิมใหม่", "พระศาสดา ﷺ กล่าวว่า: คำเหล่านี้รวบรวมสำหรับคุณในโลกนี้และปรโลก"),
        "dua_ruku_laka_raka_tu" to DuaText("ใน Ruku - ฉันคำนับคุณ", "โอ้อัลลอฮ์ ฉันได้กราบลงต่อพระองค์ ฉันได้ศรัทธาต่อพระองค์ และฉันได้มอบให้แก่พระองค์แล้ว การได้ยิน การมองเห็น จิตใจ กระดูก และเส้นเอ็นของข้าพระองค์ถูกถ่อมลงต่อพระพักตร์พระองค์", "ใน ruku (โดยเฉพาะในการสวดภาวนาโดยสมัครใจ)", "พระศาสดา ﷺ ท่องสิ่งนี้ใน ruku"),
        "dua_sujood_laka_sajadtu" to DuaText("ในซูจูด — ฉันกราบถึงคุณ", "โอ้ อัลลอฮ์ ฉันได้กราบต่อพระองค์ ฉันได้ศรัทธาต่อพระองค์ และฉันได้มอบให้แก่พระองค์แล้ว ใบหน้าของฉันกราบลงต่อพระผู้ทรงสร้างมัน ทรงปั้นมัน และทรงให้มีการได้ยินและการมองเห็นของมัน ความจำเริญเป็นของอัลลอฮ์ ผู้สร้างที่ดีที่สุด", "ในซูจูด (โดยเฉพาะในการสวดภาวนาโดยสมัครใจ)", "พระศาสดา ﷺ ท่องสิ่งนี้ในสุญูด"),
        "dua_ruku_sujood_subhanaka" to DuaText("มหาบริสุทธิ์แด่พระองค์ พระเจ้าของเรา — ยกโทษให้ฉันด้วย", "มหาบริสุทธิ์แด่พระองค์ ข้าแต่อัลลอฮฺ พระเจ้าของเรา และมวลการสรรเสริญจงมีแด่พระองค์ โอ้อัลลอฮ์ โปรดอภัยโทษให้ฉันด้วย", "ในรูกุและซูจูด", "ไอชา (RA): พระศาสดา ﷺ มักพูดสิ่งนี้ใน ruku และ sujood"),
        "dua_q_musa_li_akhi" to DuaText("Dua ของมูซา (AS) — โปรดยกโทษให้ฉันและน้องชายของฉันด้วย", "พระเจ้าของฉัน โปรดยกโทษให้ฉันและน้องชายของฉัน และยอมรับพวกเราเข้าสู่ความเมตตาของพระองค์ เพราะพระองค์คือผู้ทรงเมตตามากที่สุดในบรรดาผู้เมตตา", "การให้อภัยต่อตนเองและน้องชายหรือคนที่รัก", "ดุอาอ์มูซา (AS) ต่อฮารูน (AS)"),
        "dua_q_ufawwidu_amri" to DuaText("ฉันขอฝากกิจการของฉันไว้กับอัลลอฮ์", "และฉันขอฝากกิจการของฉันไว้กับอัลลอฮ์ แท้จริงอัลลอฮ์เป็นผู้ทรงเห็นปวงบ่าวของพระองค์", "เมื่อมีคนต่อต้านคุณและเรื่องต้องตกเป็นของอัลลอฮ์", "ถ้อยคำของผู้ศรัทธาจากหมู่ชนของฟาโรห์ อัลลอฮ์ทรงปกป้องเขาจากแผนการชั่วร้ายของพวกเขา"),
        "dua_q_hawariyyun" to DuaText("Dua ของสาวก - บันทึกเรากับพยาน", "ข้าแต่พระเจ้าของเรา เราศรัทธาต่อสิ่งที่พระองค์ประทานลงมา และเราได้ติดตามศาสนทูต ดังนั้นโปรดบันทึกพวกเราไว้ในหมู่พยานด้วย", "เพื่อความแน่วแน่ในศรัทธาและการปฏิบัติตามศาสนทูต", "ดุอาอ์ลูกศิษย์อิสา (AS)"),
        "dua_q_la_tukhzini" to DuaText("ดุอาอิบราฮิม (AS) — อย่าทำให้ฉันอับอาย", "และอย่าทำให้ฉันอับอายในวันที่พวกเขาฟื้นคืนชีพ", "ให้ปลอดภัยจากความอับอายในวันฟื้นคืนชีพ", "ดุอาอิบรอฮีม (AS) สำหรับปรโลก"),
        "dua_iftar_laka_sumtu" to DuaText("Iftar - ฉันถือศีลอดสำหรับคุณ", "โอ้อัลลอฮ์ ฉันได้ถือศีลอดเพื่อพระองค์ และด้วยปัจจัยยังชีพของพระองค์ ฉันได้ละศีลอดของฉัน", "เมื่อละศีลอด (อาละวาดอันเลื่องชื่อ)", "ท่านศาสดา ﷺ กล่าวสิ่งนี้เมื่อละศีลอด เป็นการบรรยายแบบ Mursal ที่ได้รับความเข้มแข็งจากการบรรยายอื่นๆ การละศีลอดถือเป็นการปฏิบัติของชาวฮานาฟีและคนส่วนใหญ่"),
        "dua_iftar_ibn_umar" to DuaText("Iftar - ด้วยความเมตตาอันยิ่งใหญ่ของคุณ โปรดยกโทษให้ฉันด้วย", "โอ้อัลลอฮ์ ฉันขอต่อพระองค์ด้วยความเมตตาของพระองค์ซึ่งครอบคลุมทุกสิ่งเพื่ออภัยโทษให้ฉัน", "ที่อิฟตาร์ — อับดุลลอฮ์ อิบน์ อัมร์ (RA) ทำดุอานี้; ดุอาอ์ของผู้ถือศีลอดที่ละศีลอดจะไม่ถูกปฏิเสธ", "หะดีษ: ดุอาของผู้ถือศีลอด ณ เวลาละศีลอดจะไม่ถูกปฏิเสธ"),
        "dua_inni_saim" to DuaText("เมื่อถูกยั่วยุขณะถือศีลอด", "ฉันกำลังถือศีลอด ฉันกำลังถือศีลอด", "เมื่อมีคนดูถูกคุณหรือทะเลาะกับคุณขณะถือศีลอด", "ศาสดา ﷺ กล่าวว่า: การถือศีลอดเป็นเกราะป้องกัน ดังนั้นผู้ที่ถือศีลอดไม่ควรพูดจาหยาบคายหรือกระทำการอย่างไม่รู้ — หากมีใครทะเลาะวิวาท ให้พูดสองครั้ง"),
        "dua_eid_takbeer" to DuaText("ตักเบียร์ระหว่างทางไปอีด", "อัลลอฮฺคือผู้ทรงยิ่งใหญ่ อัลลอฮ์ทรงยิ่งใหญ่ ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์ และอัลลอฮ์นั้นยิ่งใหญ่ อัลลอฮฺทรงยิ่งใหญ่ และการสรรเสริญทั้งมวลเป็นของอัลลอฮฺ", "ตั้งแต่คืนเดือนเพ็ญจนถึงวันละหมาดอีดิ้ลฟิตริ โดยเฉพาะระหว่างทางไปลานอีด", "คำสั่งอัลกุรอาน: 'เพื่อให้คุณนับให้เสร็จสิ้นและประกาศความยิ่งใหญ่ของอัลลอฮ์' (อัลบะเกาะเราะห์ 2:185) อิบนุ มัสอูด (RA) กล่าวว่าตักบีรนี้"),
        "dua_ahsin_aqibatana" to DuaText("ทำให้จุดจบของเราดีในทุกกิจการ", "โอ้อัลลอฮ์ โปรดทรงทำให้การงานของเราประสบผลสำเร็จในทุกเรื่อง และทรงปกป้องเราให้พ้นจากความอับอายในโลกนี้และการลงโทษในปรโลก", "เพื่อผลลัพธ์ที่ดีในทุกๆเรื่อง", "ใครก็ตามที่ทำดุอานี้และตายก่อนที่จะถูกทดลองก็ตาย (ปลอดภัยจากการทดลอง)"),
        "dua_fadlika_wa_rahmatik" to DuaText("ฉันขอความโปรดปรานและความเมตตาของคุณ", "โอ้อัลลอฮ์ ฉันขอความกรุณาจากพระองค์และความเมตตาจากพระองค์ เพราะไม่มีผู้ใดครอบครองสิ่งเหล่านั้นนอกจากพระองค์", "เมื่อขอเสบียงและความเมตตา", "แขกมาหาศาสดาพยากรณ์ ﷺ เมื่อไม่มีอาหาร เขาทำดุอานี้แล้วของขวัญก็มาถึง"),
        "dua_allahu_akbar_kabira_2696" to DuaText("คำศัพท์ที่สอนให้ชาวเบดูอิน", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อัลลอฮ์นั้นเป็นผู้ทรงยิ่งใหญ่อันยิ่งใหญ่ การสรรเสริญอันมากมายเป็นของอัลลอฮ์ มหาบริสุทธิ์แห่งอัลลอฮ์พระเจ้าแห่งสากลโลก และไม่มีอำนาจใด ๆ และไม่มีอำนาจใด ๆ เว้นแต่ที่อัลลอฮ์ ผู้ทรงอำนาจ ผู้ทรงปรีชาญาณ", "วลีที่ครอบคลุมของ dhikr และ dua — สอนให้กับชาวเบดูอิน", "หลังจากนั้น เขาได้รับการสอนให้กล่าวคำว่า 'อัลลอฮุมมะฆฟิร ลี วะรฮัมนี วะห์ดินี วาร์ซุกนี'"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("ขออภัยในสิ่งที่ฉันส่งก่อนและหลัง", "โอ้อัลลอฮ์ โปรดอภัยโทษแก่ฉันในความผิดที่ฉันได้กระทำทั้งก่อนและหลัง สิ่งที่ฉันได้ทำในที่ลับ และสิ่งที่ฉันทำอย่างเปิดเผย ความเกินเลยของฉัน และสิ่งที่พระองค์ทรงรู้ดียิ่งกว่าฉัน คุณคือผู้ที่นำไปข้างหน้าและผู้ที่ถอยกลับ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์", "หลังตะชะฮุดและละหมาด ก่อนสลาม", "ศาสดา ﷺ ท่องสิ่งนี้ในตอนท้ายของการละหมาดระหว่างตะชะหุดและสลาม"),
        "dua_jiddi_wa_hazli" to DuaText("ยกโทษให้กับความจริงจังและเรื่องตลกของฉัน", "โอ้อัลลอฮ์ โปรดอภัยโทษแก่ฉันในความผิดบาปที่ฉันได้กระทำอย่างจริงจังและล้อเล่น โดยไม่ได้ตั้งใจและจงใจ และทั้งหมดนั้นก็อยู่ในตัวฉัน", "การให้อภัยบาปทุกประเภท ทั้งที่รู้และไม่รู้", "istighfar ที่ครอบคลุมของศาสดา ﷺ"),
        "dua_rising_ruku_mil" to DuaText("After Ruku - สรรเสริญสวรรค์", "พระเจ้าของเรา บรรดาการสรรเสริญเป็นของพระองค์ เติมเต็มชั้นฟ้าทั้งหลาย เติมเต็มแผ่นดิน และเติมเต็มสิ่งอื่นใดที่พระองค์ต้องการหลังจากนั้น", "ภายหลังเสด็จขึ้นจากรุกูพร้อมกับ 'รับพนะ ลากัลฮัมด์'", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อลุกขึ้นจากรูกุ"),
        "dua_istiftah_kabira" to DuaText("อัลลอฮ์นั้นยิ่งใหญ่และได้รับการสรรเสริญอย่างล้นเหลือ", "อัลลอฮ์นั้นเป็นผู้ทรงยิ่งใหญ่อันยิ่งใหญ่ การสรรเสริญอันมากมายเป็นของอัลลอฮ์ และมหาบริสุทธิ์แห่งอัลลอฮฺทั้งยามเช้าและยามเย็น", "เมื่อเริ่มสวดมนต์ (การสรรเสริญเปิดรูปแบบหนึ่ง)", "ศาสดา ﷺ กล่าวว่า: ประตูสวรรค์ถูกเปิดไว้"),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) — ฉันวิงวอนต่ออัลลอฮ์เท่านั้น", "ฉันบ่นถึงความเจ็บปวดและความเศร้าโศกของฉันต่ออัลลอฮ์เท่านั้น", "ในความโศกเศร้าอย่างสุดซึ้งและการแยกจากกัน", "Ya'qub (AS) กล่าวสิ่งนี้โดยแยกจาก Yusuf (AS)"),
        "dua_q_khayrun_hafiza" to DuaText("อัลลอฮ์เป็นผู้พิทักษ์ที่ดีที่สุด", "อัลลอฮ์เป็นผู้ทรงปกป้องที่ดีที่สุด และพระองค์เป็นผู้ทรงเมตตาเสมอในหมู่ผู้เมตตา", "เมื่อส่งลูกหรือคนที่รักไปเที่ยว", "Ya'qub (AS) กล่าวสิ่งนี้ในขณะที่มอบลูกชายของเขาไว้กับอัลลอฮ์"),
        "dua_q_aqraba_rashada" to DuaText("ขอให้พระเจ้าของฉันนำทางฉันเข้าใกล้ไปทางขวามากขึ้น", "บางทีพระเจ้าของฉันจะทรงชี้นำฉันไปสู่สิ่งที่ใกล้ตัวกว่านี้เพื่อการประพฤติที่ถูกต้อง", "เมื่อแสวงหาหนทางที่ดีกว่าในเรื่องใดเรื่องหนึ่ง", "ศาสดาพยากรณ์ ﷺ ได้รับคำสั่งให้พูดสิ่งนี้เมื่อลืม"),
        "dua_q_sawa_as_sabil" to DuaText("Dua ของมูซา (AS) — นำทางฉันไปสู่ทางที่ถูกต้อง", "บางทีพระเจ้าของฉันจะทรงชี้นำฉันไปสู่ทางที่ถูกต้อง", "เมื่อออกเดินทางครั้งใหม่หรือเส้นทางที่ไม่คุ้นเคย", "มูซา (AS) พูดเช่นนี้ขณะที่เขาหันไปทางมัดยาน"),
        "dua_q_not_among_wrongdoers" to DuaText("อย่าให้ฉันอยู่ในหมู่ผู้กระทำความผิด", "พระเจ้าของฉัน โปรดอย่าให้ฉันอยู่ในหมู่ผู้อธรรมเลย", "ดุอาอฺขอให้อัลลอฮ์ทรงแยกคนหนึ่งออกจากผู้กระทำผิด", "ดุอาอฺขอให้อัลลอฮ์ทรงแยกคนหนึ่งออกจากผู้กระทำผิด"),
        "dua_q_do_not_make_us_trial" to DuaText("อย่าทำให้เราถูกทดลอง", "พระเจ้าของเรา โปรดอย่าทรงทำให้เราเป็นการทดสอบแก่บรรดาผู้ปฏิเสธศรัทธา และทรงอภัยโทษให้แก่เราด้วย พระเจ้าของเรา แท้จริงพระองค์คือผู้ทรงอำนาจ ผู้ทรงปรีชาญาณ", "ดุอาอ์อิบรอฮีม (AS) และสหายของเขา", "ดุอาอ์อิบรอฮีม (AS) และสหายของเขา"),
        "dua_morning_witness" to DuaText("พยานยามเช้าถึงเตาฮีด", "โอ้อัลลอฮ์ ฉันได้เข้ามาในตอนเช้าเพื่อวิงวอนต่อพระองค์ ผู้ทรงครองบัลลังก์ของพระองค์ มะลาอิกะฮ์ของพระองค์ และสิ่งทรงสร้างทั้งหมดของพระองค์ เพื่อเป็นพยานว่าพระองค์คืออัลลอฮ์ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ผู้เดียวดาย ปราศจากคู่ครอง และมูฮัมหมัด ﷺ เป็นผู้รับใช้และผู้ส่งสารของพระองค์", "คำบรรยายกล่าวถึงการพูดสี่ครั้งในตอนเช้า", "คำบรรยายกล่าวถึงการพูดสี่ครั้งในตอนเช้า"),
    )
}
